-- ScholarBridgeAi — Scholarship rewrite pass 39 (Norway)
-- Verified 2026-10-25 against the providers' own pages (cited in source_url).
-- All three rows in this cluster describe the same thing: Lånekassen, the Norwegian state loan and
-- grant fund. It is not a scholarship, it is not awarded by a university, and a student arriving
-- from Uzbekistan on a study permit is not entitled to it. Norway also started charging tuition to
-- non-EEA students in autumn 2023, so the money flows the other way. All three rows are retired.

-- 636 University of Oslo
UPDATE scholarships SET
  title = 'University of Oslo - Lanekassen is a loan fund for Norwegian citizens, not an international scholarship (retired)',
  description = 'Lanekassen is the Norwegian State Educational Loan Fund, and the first correction is that it is a loan and grant scheme for people with a legal affiliation to Norway rather than a scholarship a foreign applicant can win. The fund''s own rules say the main requirement is Norwegian citizenship, and list the exceptions a foreign national can use: a permanent residence permit, compelling humanitarian reasons or links to the kingdom, British citizenship under the post-2020 transitional rules, at least 24 months of continuous full-time employment in Norway immediately before starting study, or three years of continuous study in Norway totalling 180 credits - none of which a student arriving from Uzbekistan on a study permit satisfies at the point of application. The European Commission''s Eurydice country profile puts it more bluntly: international students are not included in the loans from Lanekassen, apart from Ukrainian refugees and students who have already self-financed three years of study in Norway. The second correction is about direction of money. Since autumn 2023 students from outside the EU, EEA and Switzerland pay tuition at Norwegian public universities, and Oslo publishes the rates: NOK 204,000 or NOK 295,000 a year for most English-taught master''s programmes in 2026/27, falling to NOK 186,000 or NOK 218,000 in 2027/28. On top of that the Directorate of Immigration requires proof of NOK 170,368 for a year of living costs. The December 1 date in the old record is Oslo''s application deadline for non-EU applicants, not a scholarship deadline. The old figure of USD 23,000 was invented.',
  coverage_type = 'Unspecified', award_basis = 'variable', award_amount = NULL, award_currency = 'NOK', amount_usd_value = 0,
  deadline = 'Not published', deadline_date = NULL, deadline_type = 'not_published',
  website_url = 'https://lanekassen.no/en-US/rules-and-regulations/tildeling/del1-kapittel2/foreign-nationals/foreign-nationals/',
  source_url = 'https://www.uio.no/english/studies/admission/tuition/table-of-costs/',
  verification_status = 'verified', source_reliability = 9, is_active = false,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Retired after reading two authoritative sources on 2026-10-25: the Lanekassen page on foreign nationals states that to qualify for support you must usually be a Norwegian citizen, that foreign citizens can receive support to study in Norway only if they hold a permanent residence permit or meet one of the listed exceptions - compelling humanitarian reasons or links to the kingdom, British citizenship under the transitional rules, 24 months of continuous full-time employment in Norway, or three years of continuous study in Norway totalling 180 credits - and that support for studies abroad is restricted to Norwegian citizens with narrow exceptions for EEA and EFTA citizens; the Eurydice national profile for Norway states that international students are not included in the loans from Lanekassen apart from Ukrainian refugees and students who have self-financed three years of study in Norway; the University of Oslo tuition page states that students with citizenship from outside the EU, EEA and Switzerland must pay tuition fees, that the rule applies to students admitted from 2023 onwards, and that proof of NOK 170,368 must be documented for the 2026-27 residence permit; the UiO table of costs gives the 2026-27 annual rates of NOK 204,000 and NOK 295,000 and the 2027-28 rates of NOK 186,000 and NOK 218,000 for English-taught master programmes; the UiO application pages confirm 1 December as the deadline for non-EU applicants with a 15 October opening. The Norwegian Quota Scheme that used to fund non-EU students was discontinued in 2016. CORRECTIONS: the row was titled Norwegian State Educational Loan Fund (Lanekassen), carried an invented USD 23,000, claimed all three degree levels, gave a 1 December deadline as if it were a scholarship date and presented a loan fund as a scholarship. Nothing was repriced because there is no award to price; the row is deactivated and the reasoning is kept so the claim can be checked.'
WHERE id = 636;

-- 637 Norwegian University of Science and Technology
UPDATE scholarships SET
  title = 'NTNU - Lanekassen is a loan fund for Norwegian citizens, not an international scholarship (retired)',
  description = 'The record at NTNU described the same instrument as the row at Oslo and repeated the same two errors. Lanekassen is the Norwegian State Educational Loan Fund: a loan and grant scheme for people with a legal affiliation to Norway, not a scholarship for an international applicant. The fund requires Norwegian citizenship as the main rule and admits foreign nationals only through narrow exceptions - a permanent residence permit, compelling humanitarian reasons or links to the kingdom, British citizenship under the post-2020 transitional rules, 24 months of continuous full-time work in Norway before study, or three years of continuous study in Norway totalling 180 credits. A student arriving from Uzbekistan on a study permit meets none of these at application. The second error is the direction of money. Since autumn 2023, students from outside the EU, EEA and Switzerland pay tuition at Norwegian public universities, and NTNU is no exception; the fee level is set per programme and per institution, so the figure has to be read from NTNU''s own tuition pages for the year in question rather than assumed. On top of tuition, the Directorate of Immigration requires documented living costs of NOK 170,368 for the 2026/27 academic year. The December 1 date in the old record is the non-EU application deadline at most Norwegian institutions, not a scholarship deadline, and the USD 17,477 figure was invented.',
  coverage_type = 'Unspecified', award_basis = 'variable', award_amount = NULL, award_currency = 'NOK', amount_usd_value = 0,
  deadline = 'Not published', deadline_date = NULL, deadline_type = 'not_published',
  website_url = 'https://lanekassen.no/en-US/rules-and-regulations/tildeling/del1-kapittel2/foreign-nationals/foreign-nationals/',
  source_url = 'https://lanekassen.no/en-US/rules-and-regulations/tildeling/del1-kapittel2/foreign-nationals/foreign-nationals/',
  verification_status = 'verified', source_reliability = 9, is_active = false,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Retired after reading the Lanekassen rules on foreign nationals on 2026-10-25, which state that the main requirement for support is Norwegian citizenship, that foreign citizens can receive support for study in Norway only if they hold a permanent residence permit or meet one of the listed exceptions, and that support for studies abroad is essentially limited to Norwegian and EEA or EFTA citizens; the Eurydice national profile for Norway confirms that international students are excluded from Lanekassen loans apart from Ukrainian refugees and students who have self-financed three years of study in Norway; the Norwegian policy record shows that parliament decided in 2023 that new students from outside the EEA and Switzerland must pay tuition, with refugees and exchange students exempt, and that the old Quota Scheme was discontinued in 2016; the University of Oslo documentation, used as the reference for the sector because it publishes the same national rules, gives the proof-of-funds requirement of NOK 170,368 for 2026-27 and confirms 1 December as the non-EU application deadline. CORRECTIONS: the row carried an invented USD 17,477, claimed all three degree levels, presented a loan fund as a scholarship and used the application deadline as a scholarship deadline. No NTNU-specific scholarship figure could be verified either, because Norwegian institutions do not fund international master students through entrance scholarships; the row is deactivated rather than repriced with another guess.'
WHERE id = 637;

-- 638 University of Bergen
UPDATE scholarships SET
  title = 'University of Bergen - Lanekassen is a loan fund for Norwegian citizens, not an international scholarship (retired)',
  description = 'The Bergen record was the third copy of the same mistake, with yet another invented figure, USD 15,000. Lanekassen is the Norwegian State Educational Loan Fund and it is a loan and grant scheme for people with a legal affiliation to Norway, not a scholarship open to an international applicant. The fund''s own rules make Norwegian citizenship the main requirement and allow foreign nationals only through narrow exceptions: a permanent residence permit, compelling humanitarian reasons or links to the kingdom, British citizenship under the post-2020 transitional rules, 24 months of continuous full-time employment in Norway, or three years of continuous study in Norway totalling 180 credits. A student arriving from Uzbekistan on a study permit meets none of these when applying. The second correction is that the money now runs the other way: since autumn 2023 students from outside the EU, EEA and Switzerland pay tuition at Norwegian public universities including Bergen, with the level set per programme, and separate proof of living costs of NOK 170,368 is required by the Directorate of Immigration for 2026/27. The December 1 date in the old record is the non-EU application deadline, not a scholarship deadline. Three rows describing one loan fund were also misleading in themselves: they made it look as though Oslo, Trondheim and Bergen each had their own international scholarship, which is not the case.',
  coverage_type = 'Unspecified', award_basis = 'variable', award_amount = NULL, award_currency = 'NOK', amount_usd_value = 0,
  deadline = 'Not published', deadline_date = NULL, deadline_type = 'not_published',
  website_url = 'https://lanekassen.no/en-US/rules-and-regulations/tildeling/del1-kapittel2/foreign-nationals/foreign-nationals/',
  source_url = 'https://lanekassen.no/en-US/rules-and-regulations/tildeling/del1-kapittel2/foreign-nationals/foreign-nationals/',
  verification_status = 'verified', source_reliability = 9, is_active = false,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Retired after reading the Lanekassen rules on foreign nationals on 2026-10-25, which state that Norwegian citizenship is the main requirement for support, that foreign citizens can receive support for study in Norway only through the listed exceptions, and that support for study abroad is essentially limited to Norwegian and EEA or EFTA citizens; the Eurydice national profile for Norway states that international students are not included in the Lanekassen loans apart from Ukrainian refugees and students who have self-financed three years of study in Norway; the Norwegian policy record shows that from 2023 new students from outside the EEA and Switzerland must pay tuition, with refugees and exchange students exempt, and that the Norwegian Quota Scheme that once funded non-EU students was discontinued in 2016; the University of Oslo documentation, which publishes the national rules, gives the 2026-27 proof-of-funds requirement of NOK 170,368 and the non-EU application deadline of 1 December. CORRECTIONS: the row carried an invented USD 15,000, claimed all three degree levels, presented a loan fund as a scholarship and used the application deadline as a scholarship deadline. It is one of three near-identical rows that together implied three separate university scholarships where there is only one national loan scheme, so all three are deactivated in this pass.'
WHERE id = 638;

-- university_scholarships cards
UPDATE university_scholarships u SET scholarship_name = v.name, availability_status = 'No', funding_type = 'Not applicable', max_scholarship = v.mx, covers_tuition = false, covers_living_expenses = false, eligibility_notes = v.elig, official_url = v.url, source_url = v.url, verification_status = 'verified', last_verified_at = now()
FROM (VALUES
  (151, 'University of Oslo - Lanekassen is a loan fund for Norwegian citizens', 'None: Lanekassen is a loan scheme for Norwegian citizens', 'A loan and grant fund, not a scholarship. The main requirement is Norwegian citizenship; foreign nationals qualify only with a permanent residence permit, 24 months of full-time work in Norway, or 180 credits of prior study in Norway. Non-EEA students pay tuition at Oslo - NOK 204,000 or 295,000 in 2026/27, and NOK 186,000 or 218,000 in 2027/28 - plus NOK 170,368 of documented living costs.', 'https://lanekassen.no/en-US/rules-and-regulations/tildeling/del1-kapittel2/foreign-nationals/foreign-nationals/'),
  (233, 'NTNU - Lanekassen is a loan fund for Norwegian citizens', 'None: Lanekassen is a loan scheme for Norwegian citizens', 'A loan and grant fund, not a scholarship, available in practice to Norwegian citizens and to foreign nationals with permanent residence, 24 months of full-time work in Norway or 180 credits of prior study in Norway. Non-EEA students have paid tuition at NTNU since autumn 2023, with the level set per programme.', 'https://lanekassen.no/en-US/rules-and-regulations/tildeling/del1-kapittel2/foreign-nationals/foreign-nationals/'),
  (243, 'University of Bergen - Lanekassen is a loan fund for Norwegian citizens', 'None: Lanekassen is a loan scheme for Norwegian citizens', 'A loan and grant fund, not a scholarship, available in practice to Norwegian citizens and to foreign nationals with permanent residence, 24 months of full-time work in Norway or 180 credits of prior study in Norway. Non-EEA students pay tuition at Bergen since autumn 2023, and the Directorate of Immigration requires NOK 170,368 of documented living costs for 2026/27.', 'https://lanekassen.no/en-US/rules-and-regulations/tildeling/del1-kapittel2/foreign-nationals/foreign-nationals/')
) AS v(id, name, mx, elig, url)
WHERE u.id = v.id;
